/** @internal */
export function buildWindowSpecSql(spec: WindowSpec): SQL {
	const parts: SQL[] = [];
	if (spec.partitionBy && spec.partitionBy.length > 0) {
		parts.push(sql`partition by ${sql.join(spec.partitionBy, sql`, `)}`);
	}
	if (spec.orderBy && spec.orderBy.length > 0) {
		parts.push(sql`order by ${sql.join(spec.orderBy, sql`, `)}`);
	}
	if (spec.frame) {
		parts.push(spec.frame.toSQL());
	}
	return sql.join(parts, sql` `);
}

// ─── Window function builder ─────────────────────────────────────────────

export interface WindowFunctionBuilder<T extends SQL = SQL> {
	over(spec?: WindowSpec | string): T;
}

class WindowFunctionBuilderImpl<T extends SQL = SQL> implements WindowFunctionBuilder<T> {
	constructor(
		private funcSql: SQL,
		private mapWithDecoder?: any,
	) {}

	over(spec?: WindowSpec | string): T {
		let overSql: SQL;
		if (spec === undefined) {
			overSql = sql` over ()`;
		} else if (typeof spec === 'string') {
			overSql = sql` over ${sql.identifier(spec)}`;
		} else {
			const specSql = buildWindowSpecSql(spec);
			if (specSql.queryChunks.length === 0) {
