// ─── Helper: SQL text extraction ──────────────────────────────────────────
function sqlText(sqlChunk) {
	const query = sqlChunk.toQuery({
		casing: { getColumnCasing: (col) => col.name },
		escapeName: (name) => `"${name}"`,
		escapeParam: (_num, value) => `$${_num}`,
		escapeString: (str) => `'${str.replace(/'/g, "''")}'`,
	});
	return query.sql;
}

function queryWithParams(sqlChunk) {
	return sqlChunk.toQuery({
		casing: { getColumnCasing: (col) => col.name },
		escapeName: (name) => `"${name}"`,
		escapeParam: (_num, value) => `$${_num}`,
		escapeString: (str) => `'${str.replace(/'/g, "''")}'`,
	});
}

let passed = 0;
let failed = 0;

function assert(label, condition) {
	if (condition) {
		console.log(`  ✅ ${label}`);
		passed++;
	} else {
		console.error(`  ❌ ${label}`);
		failed++;
	}
}

function assertThrows(label, fn, expectedInMessage) {
	try {
		fn();
		console.error(`  ❌ ${label} — expected error containing "${expectedInMessage}" but no error was thrown`);
		failed++;
	} catch (e) {
		if (e.message && e.message.includes(expectedInMessage)) {
			console.log(`  ✅ ${label}`);
			passed++;
		} else {
			console.error(`  ❌ ${label} — expected error containing "${expectedInMessage}", got: "${e.message}"`);
			failed++;
		}
	}
}

function assertEqual(label, actual, expected) {
	if (actual === expected) {
		console.log(`  ✅ ${label}`);
		passed++;
	} else {
		console.error(`  ❌ ${label} — expected "${expected}", got "${actual}"`);
		failed++;
	}
}

function assertZeroParams(label, sqlChunk) {
	const q = queryWithParams(sqlChunk);
	if (q.params.length === 0) {
		console.log(`  ✅ ${label}`);
		passed++;
	} else {
		console.error(`  ❌ ${label} — expected 0 params, got ${q.params.length}: ${JSON.stringify(q.params)}`);
		failed++;
	}
}

