assertEqual('windowCount().over() -> count(*)', sqlText(windowCount().over()), 'count(*) over ()');
assertEqual('windowCount(expr).over() -> count(expr)', sqlText(windowCount(sql`salary`).over()), 'count(salary) over ()');

