console.log('\n=== AC 9: ntile / nthValue reject non-positive ===\n');

assertThrows('ntile(0) throws', () => ntile(0), 'ntile');
assertThrows('ntile(-1) throws', () => ntile(-1), 'ntile');
assertThrows('ntile(-5) includes -5', () => ntile(-5), '-5');
