assertThrows('rows({from:following(5), to:currentRow})', () => rows({ from: following(5), to: currentRow }), 'from');
assertThrows('rows({from:following(3), to:preceding(2)})', () => rows({ from: following(3), to: preceding(2) }), 'from');
