func TestRetry_MaxDelayCaps(t *testing.T) {
	content := []byte("blah!")
	callCount := atomic.Int64{}

	mux := http.NewServeMux()
	mux.Handle("/", http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		callCount.Add(1)
		w.Header().Set("Retry-After", "5") // 5 seconds
		w.WriteHeader(429)
	}))

	srv := httptest.NewServer(mux)
	t.Cleanup(srv.Close)

	assetOpen = func(_ string, _ *artifact.Artifact) (*asset, error) {
		return &asset{
			ReadCloser: io.NopCloser(bytes.NewReader(content)),
			Size:       int64(len(content)),
		}, nil
	}
	t.Cleanup(assetOpenReset)

	var is2xx ResponseChecker = func(r *http.Response) error {
		if r.StatusCode/100 == 2 {
			return nil
		}
		return fmt.Errorf("unexpected http status code: %v", r.StatusCode)
	}

	ctx := testctx.WrapWithCfg(t.Context(), config.Project{
		ProjectName: "blah",
	}, testctx.WithVersion("2.1.0"))

	// delay=1s, Retry-After=5s, max_delay=2s => expected wait = min(max(1s,5s), 2s) = 2s
	upload := config.Upload{
		Mode:   ModeBinary,
		Name:   "test-maxdelay",
		Target: srv.URL + "/{{.ProjectName}}/{{.Version}}/",
		Retry: config.Retry{
			Attempts: 2,
			Delay:    1 * time.Second,
			MaxDelay: 2 * time.Second,
		},
	}

	folder := t.TempDir()
	file := filepath.Join(folder, "a.bin")
	require.NoError(t, os.WriteFile(file, content, 0o644))
	ctx.Artifacts.Add(&artifact.Artifact{
		Name: "a.bin",
		Path: file,
		Type: artifact.UploadableBinary,
	})

	start := time.Now()
	err := Upload(ctx, []config.Upload{upload}, "test", is2xx)
	elapsed := time.Since(start)
	require.Error(t, err)
	require.Equal(t, int64(2), callCount.Load())

	// Should be capped at ~2s, not 5s
	require.GreaterOrEqual(t, elapsed, 1800*time.Millisecond,
		"should wait at least ~2s, got %v", elapsed)
	require.Less(t, elapsed, 4500*time.Millisecond,
		"should be capped by max_delay, not reach 5s, got %v", elapsed)
}

