// sourceLine extracts the "# Source: <path>" line from a manifest document.
func sourceLine(doc string) string {
	first, _, _ := strings.Cut(doc, "\n")
	return first
}

// sourcePathFromDoc extracts the source path from a manifest document.
// The document is expected to start with a "# Source: <path>" line.
func sourcePathFromDoc(doc string) string {
	first := sourceLine(doc)
	if strings.HasPrefix(first, "# Source: ") {
		return strings.TrimPrefix(first, "# Source: ")
	}
	return ""
}

// stripSourceLine removes the first "# Source:" line from a manifest document.
func stripSourceLine(doc string) string {
	_, rest, found := strings.Cut(doc, "\n")
	if found && strings.HasPrefix(sourceLine(doc), "# Source: ") {
		return strings.TrimSuffix(rest, "\n")
	}
	return doc
}

// hookEntry holds a hook's source path and content for sorting.
type hookEntry struct {
	Source  string
	Content string
}

// SortBySource takes the raw assembled manifest string and a list of hooks,
// and returns a unified manifest stream sorted by Source path lexicographically.
//
// Within the same Source path, hooks are placed before non-hook resources.
// Within a single template file, multi-document YAML is emitted in the same
// top-to-bottom order as rendered.
func SortBySource(manifest string, hooks []*release.Hook) string {
	type entry struct {
		source    string
		content   string
		isHook    bool
		origOrder int
	}

	var entries []entry

	// Add hooks first, each is a separate entry
	for i, h := range hooks {
		entries = append(entries, entry{
			source:    h.Path,
			content:   h.Manifest,
			isHook:    true,
			origOrder: i,
		})
	}

	// Add non-hook manifests from the assembled manifest string
	docs := SplitManifests(manifest)
	var keys []string
	for k := range docs {
		keys = append(keys, k)
	}
	sort.Sort(BySplitManifestsOrder(keys))

	for i, k := range keys {
		doc := docs[k]
		entries = append(entries, entry{
			source:    sourcePathFromDoc(doc),
			content:   stripSourceLine(doc),
			isHook:    false,
			origOrder: i,
		})
	}

	// Sort by source path lexicographically, then hooks before non-hooks,
	// then by original order to preserve intra-file ordering
	sort.SliceStable(entries, func(i, j int) bool {
		if entries[i].source != entries[j].source {
			return entries[i].source < entries[j].source
		}
		if entries[i].isHook != entries[j].isHook {
			return entries[i].isHook // hooks come first
		}
		return entries[i].origOrder < entries[j].origOrder
	})

	// Reassemble into a unified stream
	var buf strings.Builder
	for _, e := range entries {
		if buf.Len() > 0 {
			buf.WriteString("---\n")
		}
		buf.WriteString("# Source: " + e.source + "\n")
		buf.WriteString(e.content)
		buf.WriteString("\n")
	}

	return buf.String()
}"}

