			manifest: "---\n# Source: z.yaml\nkind: ConfigMap\nmetadata:\n  name: z\n---\n# Source: a.yaml\nkind: ConfigMap\nmetadata:\n  name: a\n---\n# Source: m.yaml\nkind: ConfigMap\nmetadata:\n  name: m\n",
			hooks: nil,
			want: "---\n# Source: a.yaml\nkind: ConfigMap\nmetadata:\n  name: a\n---\n# Source: m.yaml\nkind: ConfigMap\nmetadata:\n  name: m\n---\n# Source: z.yaml\nkind: ConfigMap\nmetadata:\n  name: z\n",
		},
		{
			name: "hooks only",
			manifest: "",
			hooks: []*release.Hook{
				{Path: "b.yaml", Manifest: "kind: Job\nmetadata:\n  name: b-hook"},
				{Path: "a.yaml", Manifest: "kind: Pod\nmetadata:\n  name: a-hook"},
			},
			want: "---\n# Source: a.yaml\nkind: Pod\nmetadata:\n  name: a-hook\n---\n# Source: b.yaml\nkind: Job\nmetadata:\n  name: b-hook\n",
		},
		{
			name: "hooks before non-hooks when same source path",
			manifest: "---\n# Source: shared.yaml\nkind: ConfigMap\nmetadata:\n  name: regular\n",
			hooks: []*release.Hook{
				{Path: "shared.yaml", Manifest: "kind: Job\nmetadata:\n  name: hook-resource"},
			},
			want: "---\n# Source: shared.yaml\nkind: Job\nmetadata:\n  name: hook-resource\n---\n# Source: shared.yaml\nkind: ConfigMap\nmetadata:\n  name: regular\n",
		},
		{
			name: "multiple hooks from same source preserve original order",
			manifest: "",
			hooks: []*release.Hook{
				{Path: "shared.yaml", Manifest: "kind: Job\nmetadata:\n  name: first-hook"},
				{Path: "shared.yaml", Manifest: "kind: Pod\nmetadata:\n  name: second-hook"},
			},
			want: "---\n# Source: shared.yaml\nkind: Job\nmetadata:\n  name: first-hook\n---\n# Source: shared.yaml\nkind: Pod\nmetadata:\n  name: second-hook\n",
		},
		{
			name: "real-world mix of hooks and regular manifests",
			manifest: "---\n# Source: mychart/templates/service.yaml\napiVersion: v1\nkind: Service\nmetadata:\n  name: my-svc\n---\n# Source: mychart/templates/deployment.yaml\napiVersion: apps/v1\nkind: Deployment\nmetadata:\n  name: my-deploy\n---\n# Source: mychart/templates/tests/test.yaml\napiVersion: v1\nkind: Pod\nmetadata:\n  name: my-test\n",
			hooks: []*release.Hook{
				{Path: "mychart/templates/post-install.yaml", Manifest: "kind: Job\nmetadata:\n  name: post-install-job"},
				{Path: "mychart/templates/pre-install.yaml", Manifest: "kind: Pod\nmetadata:\n  name: pre-install-pod"},
			},
			want: "---\n# Source: mychart/templates/deployment.yaml\napiVersion: apps/v1\nkind: Deployment\nmetadata:\n  name: my-deploy\n---\n# Source: mychart/templates/post-install.yaml\nkind: Job\nmetadata:\n  name: post-install-job\n---\n# Source: mychart/templates/pre-install.yaml\nkind: Pod\nmetadata:\n  name: pre-install-pod\n---\n# Source: mychart/templates/service.yaml\napiVersion: v1\nkind: Service\nmetadata:\n  name: my-svc\n---\n# Source: mychart/templates/tests/test.yaml\napiVersion: v1\nkind: Pod\nmetadata:\n  name: my-test\n",
		},
		{
			name: "trailing newline present in output",
			manifest: "---\n# Source: a.yaml\nkind: ConfigMap\nmetadata:\n  name: a\n",
			hooks: nil,
			want: "---\n# Source: a.yaml\nkind: ConfigMap\nmetadata:\n  name: a\n",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := SortBySource(tt.manifest, tt.hooks)
			if got != tt.want {
				t.Errorf("SortBySource() =\n%q\nwant:\n%q", got, tt.want)
			}
			// Verify trailing newline (requirement 8)
			if len(got) > 0 && got[len(got)-1] != '\n' {
				t.Errorf("SortBySource() output must end with a newline")
			}
		})
	}
}

func TestExtractSourceFromDoc(t *testing.T) {
	tests := []struct {
		name string
		doc  string
		want string
	}{
		{
			name: "doc with source line",
			doc:  "# Source: mychart/templates/deploy.yaml\nkind: Deployment\n",
			want: "mychart/templates/deploy.yaml",
		},
		{
			name: "doc without newline",
			doc:  "# Source: single.yaml",
			want: "single.yaml",
		},
		{
			name: "doc without source prefix",
			doc:  "kind: ConfigMap\nmetadata:\n  name: test\n",
			want: "",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := extractSourceFromDoc(tt.doc); got != tt.want {
				t.Errorf("extractSourceFromDoc() = %q, want %q", got, tt.want)
			}
		})
	}
}

func TestStripSourceLine(t *testing.T) {
	tests := []struct {
		name string
		doc  string
		want string
	}{
		{
			name: "doc with source line",
			doc:  "# Source: mychart/templates/deploy.yaml\nkind: Deployment\n",
			want: "kind: Deployment\n",
		},
		{
			name: "doc without newline",
			doc:  "# Source: single.yaml",
			want: "",
		},
		{
			name: "doc without source prefix",
			doc:  "kind: ConfigMap\nmetadata:\n  name: test\n",
			want: "kind: ConfigMap\nmetadata:\n  name: test\n",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := stripSourceLine(tt.doc); got != tt.want {
				t.Errorf("stripSourceLine() = %q, want %q", got, tt.want)
			}
		})
	}
}"}

