	require.NoError(t, err)

	// Write in a goroutine — it will block when the pipe buffer fills.
	writeDone := make(chan bool)
	go func() {
		big := make([]byte, 1024*1024) // 1MB should fill the pipe
		stream.Write(big)
		writeDone <- true
	}()

	// Give the write time to get blocked.
	time.Sleep(50 * time.Millisecond)

	// Now close the session. This should return promptly without waiting for
	// the blocked write to complete.
	start := time.Now()
	err = client.Close()
	elapsed := time.Since(start)

	require.NoError(t, err)
	assert.Less(t, elapsed, 2*time.Second,
		"Close() should return promptly, not wait for blocked writes")
	t.Logf("Close() returned in %v", elapsed)

	// The writer should get unblocked with an error.
	<-writeDone
}
