{"file_path": "mux_test.go", "content": "package kcp

import (
	"io"
	"net"
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

// pipePair creates a pair of connected MuxSessions over net.Pipe for testing.
// The client side uses odd stream IDs, server side uses even stream IDs.
func pipePair(t testing.TB, cfg *MuxConfig) (client, server *MuxSession) {
	t.Helper()
	c, s := net.Pipe()

	clientCfg := DefaultMuxConfig()
	clientCfg.Side = MuxSideClient
	serverCfg := DefaultMuxConfig()
	serverCfg.Side = MuxSideServer

	// Apply custom config overrides if provided
	if cfg != nil {
		if cfg.MaxFrameSize > 0 {
			clientCfg.MaxFrameSize = cfg.MaxFrameSize
			serverCfg.MaxFrameSize = cfg.MaxFrameSize
		}
		if cfg.SendWindow > 0 {
			clientCfg.SendWindow = cfg.SendWindow
			serverCfg.SendWindow = cfg.SendWindow
		}
		if cfg.RecvWindow > 0 {
			clientCfg.RecvWindow = cfg.RecvWindow
			serverCfg.RecvWindow = cfg.RecvWindow
		}
	}

	var err error
	client, err = NewMuxSession(c, &clientCfg)
	if err != nil {
		t.Fatal("NewMuxSession(client):", err)
	}
	server, err = NewMuxSession(s, &serverCfg)
	if err != nil {
		t.Fatal("NewMuxSession(server):", err)
	}
	return
}

func closePair(t testing.TB, client, server *MuxSession) {
	t.Helper()
	client.Close()
	server.Close()
}

func TestMuxSessionClose(t *testing.T) {
	client, server := pipePair(t, nil)
	defer closePair(t, client, server)

	if err := client.Close(); err != nil {
		t.Fatal("client.Close():", err)
	}
}

func TestMuxOpenAccept(t *testing.T) {
	client, server := pipePair(t, nil)
	defer closePair(t, client, server)

	// Client opens a stream
	var (
		cst *MuxStream
		sst *MuxStream
		wg  sync.WaitGroup
	)

	wg.Add(1)
	go func() {
		defer wg.Done()
		var err error
		cst, err = client.OpenStream(MuxPriorityNormal)
		if err != nil {
			t.Error("client.OpenStream:", err)
		}
	}()

	wg.Add(1)
	go func() {
		defer wg.Done()
		var err error
		sst, err = server.AcceptStream()
		if err != nil {
			t.Error("server.AcceptStream:", err)
		}
	}()

	wg.Wait()

	if cst == nil || sst == nil {
		t.Fatal("streams should not be nil")
	}

	// Check ID parity
	if cst.ID()%2 != 1 {
		t.Errorf("client stream ID %d should be odd", cst.ID())
	}
	if sst.ID()%2 != 0 {
		t.Errorf("server stream ID %d should be even", sst.ID())
	}
	// IDs should match (same stream, different sides)
	if cst.ID() != sst.ID() {
		t.Errorf("stream IDs should match: client=%d server=%d", cst.ID(), sst.ID())
	}
}

func TestMuxOpenAcceptServerSide(t *testing.T) {
	client, server := pipePair(t, nil)
	defer closePair(t, client, server)

	// Server opens a stream to client
	var (
		sst *MuxStream
		cst *MuxStream
		wg  sync.WaitGroup
	)

	wg.Add(1)
	go func() {
		defer wg.Done()
		var err error
		sst, err = server.OpenStream(MuxPriorityHigh)
		if err != nil {
			t.Error("server.OpenStream:", err)
		}
	}()

	wg.Add(1)
	go func() {
		defer wg.Done()
		var err error
		cst, err = client.AcceptStream()
		if err != nil {
			t.Error("client.AcceptStream:", err)
		}
	}()

	wg.Wait()

	if cst == nil || sst == nil {
		t.Fatal("streams should not be nil")
	}

	if sst.ID()%2 != 0 {
		t.Errorf("server stream ID %d should be even", sst.ID())
	}
	if cst.ID()%2 != 1 {
		t.Errorf("client stream ID %d should be odd", cst.ID())
	}
	if cst.ID() != sst.ID() {
		t.Errorf("stream IDs should match: client=%d server=%d", cst.ID(), sst.ID())
	}

	_ = sst
	_ = cst
}

func TestMuxDataTransfer(t *testing.T) {
	client, server := pipePair(t, nil)
	defer closePair(t, client, server)

	var (
		cst *MuxStream
		sst *MuxStream
		wg  sync.WaitGroup
	)

	// Open stream from client
	wg.Add(1)
	go func() {
		defer wg.Done()
		var err error
		cst, err = client.OpenStream(MuxPriorityNormal)
		if err != nil {
			t.Error("client.OpenStream:", err)
		}
	}()
	wg.Add(1)
	go func() {
		defer wg.Done()
		var err error
		sst, err = server.AcceptStream()
		if err != nil {
			t.Error("server.AcceptStream:", err)
		}
	}()
	wg.Wait()

	if cst == nil || sst == nil {
		t.Fatal("streams should not be nil")
	}

	// Send data from client to server
	msg := []byte("hello mux world")
	wg.Add(1)
	go func() {
		defer wg.Done()
		n, err := cst.Write(msg)
		if err != nil {
			t.Error("cst.Write:", err)
			return
		}
		if n != len(msg) {
			t.Errorf("short write: %d != %d", n, len(msg))
		}
	}()

	buf := make([]byte, 4096)
	n, err := sst.Read(buf)
	if err != nil {
		t.Fatal("sst.Read:", err)
	}
	if n != len(msg) {
		t.Fatalf("read %d bytes, expected %d", n, len(msg))
	}
	if string(buf[:n]) != string(msg) {
		t.Fatalf("got %q, expected %q", string(buf[:n]), string(msg))
	}

	wg.Wait()
}

func TestMuxBidirectionalData(t *testing.T) {
	client, server := pipePair(t, nil)
	defer closePair(t, client, server)

	var (
		cst *MuxStream
		sst *MuxStream
		wg  sync.WaitGroup
	)

	wg.Add(1)
	go func() {
		defer wg.Done()
		var err error
		cst, err = client.OpenStream(MuxPriorityNormal)
		if err != nil {
			t.Error("client.OpenStream:", err)
		}
	}()
	wg.Add(1)
	go func() {
		defer wg.Done()
		var err error
		sst, err = server.AcceptStream()
		if err != nil {
			t.Error("server.AcceptStream:", err)
		}
	}()
	wg.Wait()

	if cst == nil || sst == nil {
		t.Fatal("streams should not be nil")
	}

	// Send from client to server
	msg1 := []byte("from client")
	wg.Add(1)
	go func() {
		defer wg.Done()
		n, err := cst.Write(msg1)
		if err != nil {
			t.Error("cst.Write:", err)
			return
		}
		if n != len(msg1) {
			t.Errorf("short write: %d != %d", n, len(msg1))
		}
	}()

	// Send from server to client
	msg2 := []byte("from server")
	wg.Add(1)
	go func() {
		defer wg.Done()
		n, err := sst.Write(msg2)
		if err != nil {
			t.Error("sst.Write:", err)
			return
		}
		if n != len(msg2) {
			t.Errorf("short write: %d != %d", n, len(msg2))
		}
	}()

	// Read server side
	buf := make([]byte, 4096)
	n, err := sst.Read(buf)
	if err != nil {
		t.Fatal("sst.Read:", err)
	}
	if string(buf[:n]) != string(msg1) {
		t.Fatalf("server got %q, expected %q", string(buf[:n]), string(msg1))
	}

	// Read client side
	n, err = cst.Read(buf)
	if err != nil {
		t.Fatal("cst.Read:", err)
	}
	if string(buf[:n]) != string(msg2) {
		t.Fatalf("client got %q, expected %q", string(buf[:n]), string(msg2))
	}

	wg.Wait()
}

func TestMuxConcurrentStreams(t *testing.T) {
	client, server := pipePair(t, nil)
	defer closePair(t, client, server)

	numStreams := 5
	var wg sync.WaitGroup

	acceptDone := make(chan struct{})
	go func() {
		for i := 0; i < numStreams; i++ {
			_, err := server.AcceptStream()
			if err != nil {
				t.Error("server.AcceptStream:", err)
				return
			}
		}
		close(acceptDone)
	}()

	for i := 0; i < numStreams; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			st, err := client.OpenStream(MuxPriorityNormal)
			if err != nil {
				t.Error("OpenStream:", err)
				return
			}
			msg := []byte("stream data")
			n, err := st.Write(msg)
			if err != nil {
				t.Error("Write:", err)
				return
			}
			if n != len(msg) {
				t.Errorf("short write: %d != %d", n, len(msg))
			}
		}(i)
	}

	wg.Wait()
	<-acceptDone
}

func TestMuxFlowControl(t *testing.T) {
	// Use a small send window to trigger flow control
	cfg := DefaultMuxConfig()
	cfg.SendWindow = 100   // tiny send window
	cfg.RecvWindow = 65536 // normal receive window

	client, server := pipePair(t, &cfg)
	defer closePair(t, client, server)

	var (
		cst *MuxStream
		sst *MuxStream
		wg  sync.WaitGroup
	)

	wg.Add(1)
	go func() {
		defer wg.Done()
		var err error
		cst, err = client.OpenStream(MuxPriorityNormal)
		if err != nil {
			t.Error("client.OpenStream:", err)
		}
	}()
	wg.Add(1)
	go func() {
		defer wg.Done()
		var err error
		sst, err = server.AcceptStream()
		if err != nil {
			t.Error("server.AcceptStream:", err)
		}
	}()
	wg.Wait()

	if cst == nil || sst == nil {
		t.Fatal("streams should not be nil")
	}

	// Write enough to exhaust send window
	bigMsg := make([]byte, 300)

	writeDone := make(chan struct{})
	go func() {
		n, err := cst.Write(bigMsg)
		if err != nil {
			t.Error("cst.Write:", err)
		}
		if n != len(bigMsg) {
			t.Errorf("short write: %d != %d", n, len(bigMsg))
		}
		close(writeDone)
	}()

	// Read on server side to drain and trigger window updates
	buf := make([]byte, 4096)
	total := 0
	for total < len(bigMsg) {
		n, err := sst.Read(buf)
		if err != nil {
			t.Fatal("sst.Read:", err)
		}
		total += n
	}

	<-writeDone
}

func TestMuxHalfClose(t *testing.T) {
	client, server := pipePair(t, nil)
	defer closePair(t, client, server)

	var (
		cst *MuxStream
		sst *MuxStream
		wg  sync.WaitGroup
	)

	wg.Add(1)
	go func() {
		defer wg.Done()
		var err error
		cst, err = client.OpenStream(MuxPriorityNormal)
		if err != nil {
			t.Error("client.OpenStream:", err)
		}
	}()
	wg.Add(1)
	go func() {
		defer wg.Done()
		var err error
		sst, err = server.AcceptStream()
		if err != nil {
			t.Error("server.AcceptStream:", err)
		}
	}()
	wg.Wait()

	if cst == nil || sst == nil {
		t.Fatal("streams should not be nil")
	}

	// Send data before close
	msg := []byte("data before close")
	writeDone := make(chan struct{})
	go func() {
		n, err := cst.Write(msg)
		if err != nil {
			t.Error("cst.Write:", err)
		}
		if n != len(msg) {
			t.Errorf("short write: %d != %d", n, len(msg))
		}
		close(writeDone)
	}()

	// Read the data on server
	buf := make([]byte, 4096)
	n, err := sst.Read(buf)
	if err != nil {
		t.Fatal("sst.Read:", err)
	}
	if string(buf[:n]) != string(msg) {
		t.Fatalf("got %q, expected %q", string(buf[:n]), string(msg))
	}
	<-writeDone

	// Client half-closes
	if err := cst.Close(); err != nil {
		t.Fatal("cst.Close:", err)
	}

	// Server should now read EOF (remote closed, buffered data drained)
	_, err = sst.Read(buf)
	if err != io.EOF {
		t.Fatalf("expected EOF after remote close, got %v", err)
	}
}

func TestMuxHalfCloseBufferedData(t *testing.T) {
