		var err error
		sst, err = server.AcceptStream()
		if err != nil {
			t.Error("server.AcceptStream:", err)
		}
	}()
	wg.Wait()

	// Send data, then close
	msg := []byte("buffered data")
	done := make(chan struct{})
	go func() {
		cst.Write(msg)
		cst.Close()
		close(done)
	}()

	// Server should still be able to read after local close
	buf := make([]byte, 4096)
	n, err := sst.Read(buf)
	if err != nil {
		t.Fatal("sst.Read:", err)
	}
	if string(buf[:n]) != string(msg) {
		t.Fatalf("got %q, expected %q", string(buf[:n]), string(msg))
	}

	// Second read should get EOF (remote closed and data drained)
	_, err = sst.Read(buf)
	if err != io.EOF {
		t.Fatalf("expected EOF, got %v", err)
	}

	<-done
}

func TestMuxReadDeadline(t *testing.T) {
