		sst, _ = server.AcceptStream()
	}()
	wg.Wait()

	if sst == nil {
		t.Fatal("server stream is nil")
	}

	// Set a short deadline
	if err := sst.SetReadDeadline(time.Now().Add(10 * time.Millisecond)); err != nil {
		t.Fatal("SetReadDeadline:", err)
