func TestMuxSNMPCounters(t *testing.T) {
	// Reset SNMP counters
	DefaultSnmp.Reset()

	client, server := pipePair(t, nil)
	defer closePair(t, client, server)

	var (
		cst *MuxStream
		sst *MuxStream
		wg  sync.WaitGroup
	)

	wg.Add(1)
	go func() {
		defer wg.Done()
		cst, _ = client.OpenStream(MuxPriorityNormal)
	}()
	wg.Add(1)
	go func() {
		defer wg.Done()
		sst, _ = server.AcceptStream()
	}()
	wg.Wait()

	if cst == nil || sst == nil {
		t.Fatal("streams should not be nil")
	}

	// Check MuxStreamsOpened
	if n := atomic.LoadUint64(&DefaultSnmp.MuxStreamsOpened); n != 2 {
		t.Errorf("MuxStreamsOpened = %d, want 2 (client + server)", n)
	}

	// Send some data
	msg := []byte("snmp test data")
	done := make(chan struct{})
	go func() {
		cst.Write(msg)
		close(done)
	}()

	buf := make([]byte, 4096)
	n, err := sst.Read(buf)
	if err != nil {
		t.Fatal("sst.Read:", err)
	}
	<-done

	// Check data bytes received
	if nReceived := atomic.LoadUint64(&DefaultSnmp.MuxBytesReceived); nReceived != uint64(n) {
		t.Errorf("MuxBytesReceived = %d, want %d", nReceived, n)
	}
	if nSent := atomic.LoadUint64(&DefaultSnmp.MuxBytesSent); nSent != uint64(n) {
		t.Errorf("MuxBytesSent = %d, want %d", nSent, n)
	}

	// Close streams and check MuxStreamsClosed
	cst.Close()

	time.Sleep(50 * time.Millisecond)

	if nClosed := atomic.LoadUint64(&DefaultSnmp.MuxStreamsClosed); nClosed == 0 {
		t.Error("MuxStreamsClosed should be > 0 after close")
	}

	// Check frames
	if nFramesSent := atomic.LoadUint64(&DefaultSnmp.MuxFramesSent); nFramesSent == 0 {
		t.Error("MuxFramesSent should be > 0")
	}
	if nFramesReceived := atomic.LoadUint64(&DefaultSnmp.MuxFramesReceived); nFramesReceived == 0 {
		t.Error("MuxFramesReceived should be > 0")
	}
}

func TestMuxStreamRemoveAfterDrain(t *testing.T) {
	client, server := pipePair(t, nil)
	defer closePair(t, client, server)

	var (
		cst *MuxStream
		sst *MuxStream
		wg  sync.WaitGroup
	)

	wg.Add(1)
	go func() {
		defer wg.Done()
		cst, _ = client.OpenStream(MuxPriorityNormal)
	}()
	wg.Add(1)
	go func() {
		defer wg.Done()
		sst, _ = server.AcceptStream()
	}()
	wg.Wait()

	if cst == nil || sst == nil {
		t.Fatal("streams should not be nil")
	}

	id := cst.ID()

	// Both sides should have the stream
	if n := client.NumStreams(); n != 1 {
		t.Errorf("client NumStreams = %d, want 1", n)
	}
	if n := server.NumStreams(); n != 1 {
		t.Errorf("server NumStreams = %d, want 1", n)
	}

	// Send data, then close both sides
	msg := []byte("drain test")
	done := make(chan struct{})
	go func() {
		cst.Write(msg)
		cst.Close()
		close(done)
	}()

	// Server reads data and closes
	buf := make([]byte, 4096)
	sst.Read(buf)
	sst.Close()

	<-done

	// Give time for stream removal
	time.Sleep(50 * time.Millisecond)

	// Stream should be removed from both sides
	client.mu.Lock()
	_, clientExists := client.streams[id]
	client.mu.Unlock()
	if clientExists {
		t.Error("client stream should be removed after both sides closed and drained")
	}

	server.mu.Lock()
	_, serverExists := server.streams[id]
	server.mu.Unlock()
	if serverExists {
		t.Error("server stream should be removed after both sides closed and drained")
	}
}

