import type { Relation } from '../relation/types';
import { isRelation } from '../relation/utils/is-relation';
import type { Trait } from '../trait/types';
import type { TraitRegistry } from './types';

function isTraitOrRelation(value: unknown): value is Trait | Relation {
    if (typeof value !== 'function' && typeof value !== 'object') return false;
    if (value === null) return false;

    const obj = value as Record<symbol, unknown>;
    // A Relation has a brand symbol; a Trait is a function with an [$internal] property
    return (
        typeof value === 'function' ||
        (typeof value === 'object' && $internal in obj) ||
        Symbol.for('koota.relation') in obj ||
        Symbol.for('koota.relationPair') in obj
    );
}

/**
 * Creates a trait registry from an array of [name, trait_or_relation] tuples.
 *
 * The registry maps string names to traits or relations for use with
 * snapshot/rollback operations.
 *
 * @param entries - Array of [name, trait | relation] tuples
 * @returns A TraitRegistry with forward and reverse lookups
 * @throws Error if a name, trait, or relation is duplicated
 */
export function createTraitRegistry(
    ...entries: Array<[string, Trait | Relation]>
): TraitRegistry {
    const byName = new Map<string, RegistryEntry>();
    const byTraitId = new Map<number, RegistryEntry>();
    const seenRelations = new Set<Relation>();

    for (const [name, entry] of entries) {
        if (byName.has(name)) {
            throw new Error(`Snapshot: Duplicate registry key "${name}"`);
        }

        if (isRelation(entry)) {
            const relation = entry as Relation;
            const trait = relation[$internal].trait;

            if (byTraitId.has(trait.id)) {
                throw new Error(
                    `Snapshot: Duplicate trait for relation "${name}" (trait ID ${trait.id})`
                );
            }
            if (seenRelations.has(relation)) {
                throw new Error(`Snapshot: Duplicate relation "${name}"`);
            }

            const registryEntry: RegistryEntry = {
                type: 'relation',
                name,
                relation,
                trait,
            };
            byName.set(name, registryEntry);
            byTraitId.set(trait.id, registryEntry);
            seenRelations.add(relation);
        } else {
            const trait = entry as Trait;

            if (byTraitId.has(trait.id)) {
                throw new Error(
                    `Snapshot: Duplicate trait "${name}" (trait ID ${trait.id})`
                );
            }

            const registryEntry: RegistryEntry = {
                type: 'trait',
                name,
                trait,
            };
            byName.set(name, registryEntry);
            byTraitId.set(trait.id, registryEntry);
        }
    }

    return { byName, byTraitId };
}

// Re-export the type locally for use within this module
type RegistryEntry = import('./types').RegistryEntry;
