import { beforeEach, describe, expect, it } from 'vitest';
import {
    createTraitRegistry,
    createWorld,
    diffEntitySnapshots,
    diffWorldSnapshots,
    relation,
    rollbackEntity,
    rollbackWorld,
    snapshotEntity,
    snapshotWorld,
    trait,
    type EntitySnapshot,
    type WorldSnapshot,
    universe,
} from '../src';

// Traits for testing
const Position = trait({ x: 0, y: 0 });
const Velocity = trait({ vx: 0, vy: 0 });
const Health = trait({ hp: 100 });
const Tag = trait();
const Name = trait({ name: '' });
const Score = trait({ score: 0 });

// Relations for testing
const ChildOf = relation({ exclusive: true });
const Likes = relation({ store: { level: 0 as number } });
const Blocks = relation();

describe('createTraitRegistry', () => {
    it('should create a registry from trait/relation entries', () => {
        const registry = createTraitRegistry(
            ['position', Position],
            ['velocity', Velocity],
            ['tag', Tag]
        );

        expect(registry).toBeDefined();
        expect(registry.keys).toBeDefined();
        expect(registry.keys).toContain('position');
        expect(registry.keys).toContain('velocity');
        expect(registry.keys).toContain('tag');
    });

    it('should include relations in the registry', () => {
        const registry = createTraitRegistry(
            ['position', Position],
            ['child-of', ChildOf],
            ['likes', Likes]
        );

        expect(registry.keys).toContain('child-of');
        expect(registry.keys).toContain('likes');
    });

    it('should throw Error on duplicate keys', () => {
        expect(() =>
            createTraitRegistry(
                ['position', Position],
                ['position', Velocity]
            )
        ).toThrow(Error);
    });

    it('should throw Error on duplicate trait', () => {
        expect(() =>
            createTraitRegistry(
                ['pos1', Position],
                ['pos2', Position]
            )
        ).toThrow(Error);
    });

    it('should throw Error on duplicate relation', () => {
        expect(() =>
            createTraitRegistry(
                ['child1', ChildOf],
                ['child2', ChildOf]
            )
        ).toThrow(Error);
    });
});

describe('snapshotEntity', () => {
    let world: ReturnType<typeof createWorld>;
    let registry: ReturnType<typeof createTraitRegistry>;

    beforeEach(() => {
        universe.reset();
        world = createWorld();
        registry = createTraitRegistry(
            ['position', Position],
            ['velocity', Velocity],
            ['health', Health],
            ['tag', Tag],
            ['name', Name],
            ['score', Score],
            ['child-of', ChildOf],
            ['likes', Likes],
            ['blocks', Blocks]
        );
    });

    it('should snapshot a simple tag trait entity', () => {
        const entity = world.spawn(Tag);
        const snapshot = snapshotEntity(world, entity, registry);

        expect(snapshot.id).toBe(entity.id());
        expect(snapshot.traits).toEqual({ tag: true });
    });

    it('should snapshot a data trait entity with deep copy', () => {
        const entity = world.spawn(Position({ x: 10, y: 20 }));
        const snapshot = snapshotEntity(world, entity, registry);

        expect(snapshot.traits).toEqual({ position: { x: 10, y: 20 } });

        // Verify deep copy isolation
        const posData = snapshot.traits.position as { x: number; y: number };
        posData.x = 999;
        expect(entity.get(Position)!.x).toBe(10);
    });

    it('should snapshot entity with multiple traits', () => {
        const entity = world.spawn(Position({ x: 1, y: 2 }), Velocity({ vx: 3, vy: 4 }), Tag);
        const snapshot = snapshotEntity(world, entity, registry);

        expect(snapshot.traits).toEqual({
            position: { x: 1, y: 2 },
            velocity: { vx: 3, vy: 4 },
            tag: true,
        });
    });

    it('should snapshot entity with relations', () => {
        const target = world.spawn();
        const entity = world.spawn(ChildOf(target), Likes(target, { level: 5 }));

        const snapshot = snapshotEntity(world, entity, registry);

        expect(snapshot.traits).toEqual({});
        expect(snapshot.relations).toBeDefined();
        expect(snapshot.relations!['child-of']).toBeDefined();
        expect(snapshot.relations!['child-of']).toHaveLength(1);
        expect(snapshot.relations!['child-of']![0].targetId).toBe(target.id());
        expect(snapshot.relations!['likes']).toBeDefined();
        expect(snapshot.relations!['likes']).toHaveLength(1);
        expect(snapshot.relations!['likes']![0].targetId).toBe(target.id());
        // Likes has a store with 'level' data
        expect(snapshot.relations!['likes']![0].data).toEqual({ level: 5 });
    });

    it('should deep copy relation data', () => {
        const target = world.spawn();
        const entity = world.spawn(Likes(target, { level: 3 }));

        const snapshot = snapshotEntity(world, entity, registry);
        const data = snapshot.relations!['likes']![0].data! as { level: number };
        data.level = 999;

        // Verify the original is unchanged (deep copy)
        const stored = entity.get(Likes(target)) as { level: number } | undefined;
        expect(stored!.level).toBe(3);
    });

    it('should omit relations property when entity has no relations', () => {
        const entity = world.spawn(Position({ x: 0, y: 0 }));
        const snapshot = snapshotEntity(world, entity, registry);

        expect(snapshot.traits).toEqual({ position: { x: 0, y: 0 } });
        expect(snapshot.relations).toBeUndefined();
    });

    it('should include relations with store-less relation (tag-like)', () => {
        const target = world.spawn();
        const entity = world.spawn(Blocks(target));

        const snapshot = snapshotEntity(world, entity, registry);

        expect(snapshot.relations).toBeDefined();
        expect(snapshot.relations!['blocks']).toBeDefined();
        expect(snapshot.relations!['blocks']).toHaveLength(1);
        expect(snapshot.relations!['blocks']![0].targetId).toBe(target.id());
        expect(snapshot.relations!['blocks']![0].data).toBeUndefined();
    });

    it('should throw Error for destroyed entity', () => {
        const entity = world.spawn(Position({ x: 1, y: 2 }));
        entity.destroy();

        expect(() => snapshotEntity(world, entity, registry)).toThrow(Error);
    });

    it('should throw Error for unregistered trait', () => {
        const entity = world.spawn(Position({ x: 1, y: 2 }));
        const smallRegistry = createTraitRegistry(['velocity', Velocity]);

        expect(() => snapshotEntity(world, entity, smallRegistry)).toThrow(Error);
    });

    it('should throw Error for unregistered relation', () => {
        const target = world.spawn();
        const entity = world.spawn(ChildOf(target));
        const noRelationRegistry = createTraitRegistry(['position', Position]);

        expect(() => snapshotEntity(world, entity, noRelationRegistry)).toThrow(Error);
    });
});

describe('snapshotWorld', () => {
    let world: ReturnType<typeof createWorld>;
    let registry: ReturnType<typeof createTraitRegistry>;

    beforeEach(() => {
        universe.reset();
        world = createWorld();
        registry = createTraitRegistry(
            ['position', Position],
            ['velocity', Velocity],
            ['tag', Tag],
            ['child-of', ChildOf],
            ['likes', Likes],
            ['blocks', Blocks]
        );
    });

    it('should snapshot all entities excluding the internal world entity', () => {
        const entity1 = world.spawn(Position({ x: 1, y: 2 }));
        const entity2 = world.spawn(Tag);

        const snapshot = snapshotWorld(world, registry);

        expect(snapshot.entities).toHaveLength(2);

        const ids = snapshot.entities.map((e) => e.id).sort();
        expect(ids).toEqual([entity1.id(), entity2.id()].sort());
    });

    it('should return empty array when only world entity exists', () => {
        const snapshot = snapshotWorld(world, registry);

        expect(snapshot.entities).toHaveLength(0);
    });

    it('should capture traits and relations for all entities', () => {
        const target = world.spawn();
        const entity1 = world.spawn(Position({ x: 10, y: 20 }));
        const entity2 = world.spawn(Tag, ChildOf(target));

        const snapshot = snapshotWorld(world, registry);

        const e1 = snapshot.entities.find((e) => e.id === entity1.id())!;
        expect(e1.traits).toEqual({ position: { x: 10, y: 20 } });

        const e2 = snapshot.entities.find((e) => e.id === entity2.id())!;
        expect(e2.traits).toEqual({ tag: true });
        expect(e2.relations).toBeDefined();
        expect(e2.relations!['child-of']).toHaveLength(1);
        expect(e2.relations!['child-of']![0].targetId).toBe(target.id());
    });
});

describe('rollbackEntity', () => {
    let world: ReturnType<typeof createWorld>;
    let registry: ReturnType<typeof createTraitRegistry>;

    beforeEach(() => {
        universe.reset();
        world = createWorld();
        registry = createTraitRegistry(
            ['position', Position],
            ['velocity', Velocity],
            ['health', Health],
            ['tag', Tag],
            ['name', Name],
            ['child-of', ChildOf],
            ['likes', Likes],
            ['blocks', Blocks]
        );
    });

    it('should restore an entity to match its snapshot', () => {
        const entity = world.spawn(Position({ x: 1, y: 2 }), Velocity({ vx: 3, vy: 4 }));

        // Change the entity
        entity.set(Position, { x: 100, y: 200 });
        entity.remove(Velocity);
        entity.add(Tag);

        // Snapshot taken before changes
        const snapshot = snapshotEntity(world, entity, registry);
        // Actually we need the snapshot from before. Let me restructure.
        // Instead, let's snapshot after changes, then rollback to a different state.

        const targetSnapshot: EntitySnapshot = {
            id: entity.id(),
            traits: { position: { x: 1, y: 2 }, velocity: { vx: 3, vy: 4 } },
        };

        rollbackEntity(world, entity, registry, targetSnapshot);

        expect(entity.get(Position)).toEqual({ x: 1, y: 2 });
        expect(entity.get(Velocity)).toEqual({ vx: 3, vy: 4 });
        expect(entity.has(Tag)).toBe(false);
    });

    it('should remove traits not in the snapshot', () => {
        const entity = world.spawn(Position({ x: 1, y: 2 }), Tag);

        const snapshot: EntitySnapshot = {
            id: entity.id(),
            traits: { position: { x: 1, y: 2 } },
        };

        rollbackEntity(world, entity, registry, snapshot);

        expect(entity.has(Position)).toBe(true);
        expect(entity.has(Tag)).toBe(false);
    });

    it('should add traits that are in the snapshot but not on the entity', () => {
        const entity = world.spawn(Position({ x: 0, y: 0 }));

        const snapshot: EntitySnapshot = {
            id: entity.id(),
            traits: { position: { x: 5, y: 10 }, tag: true },
        };

        rollbackEntity(world, entity, registry, snapshot);

        expect(entity.get(Position)).toEqual({ x: 5, y: 10 });
        expect(entity.has(Tag)).toBe(true);
    });

    it('should update existing trait data to match snapshot', () => {
        const entity = world.spawn(Position({ x: 0, y: 0 }));

