            ],
        };

        expect(() => rollbackWorld(world, registry, checkpoint)).toThrow(Error);
    });

    it('should throw Error for dangling relation target', () => {
        const checkpoint: WorldSnapshot = {
            entities: [
                { id: 1, traits: {} },
                { id: 2, traits: {}, relations: { 'child-of': [{ targetId: 9999 }] } },
            ],
        };

        expect(() => rollbackWorld(world, registry, checkpoint)).toThrow(Error);
    });

    it('should create relations from checkpoint', () => {
        const checkpoint: WorldSnapshot = {
            entities: [
                { id: 10, traits: {} },
                { id: 20, traits: {}, relations: { 'child-of': [{ targetId: 10 }] } },
            ],
        };

        rollbackWorld(world, registry, checkpoint);

        const e20 = world.entities.find((e) => e.id() === 20)!;
        expect(e20).toBeDefined();
        expect(e20.has(ChildOf(10))).toBe(true);
    });

    it('should create relations with data from checkpoint', () => {
        const checkpoint: WorldSnapshot = {
            entities: [
                { id: 10, traits: {} },
                { id: 20, traits: {}, relations: { 'likes': [{ targetId: 10, data: { level: 7 } }] } },
            ],
        };

        rollbackWorld(world, registry, checkpoint);

        const e20 = world.entities.find((e) => e.id() === 20)!;
        const likesData = e20.get(Likes(10)) as { level: number } | undefined;
        expect(likesData!.level).toBe(7);
