        const result = diffEntitySnapshots(a, b);

        expect(result.addedTraits).toEqual(['velocity']);
        expect(result.removedTraits).toEqual([]);
        expect(result.changedTraits).toEqual([]);
    });

    it('should detect removed traits', () => {
        const a: EntitySnapshot = { id: 1, traits: { position: { x: 0, y: 0 }, velocity: { vx: 1, vy: 2 } } };
        const b: EntitySnapshot = { id: 1, traits: { position: { x: 0, y: 0 } } };

        const result = diffEntitySnapshots(a, b);

        expect(result.addedTraits).toEqual([]);
        expect(result.removedTraits).toEqual(['velocity']);
        expect(result.changedTraits).toEqual([]);
    });

    it('should detect changed traits using shallow equality', () => {
        const a: EntitySnapshot = { id: 1, traits: { position: { x: 0, y: 0 } } };
        const b: EntitySnapshot = { id: 1, traits: { position: { x: 5, y: 10 } } };

        const result = diffEntitySnapshots(a, b);

        expect(result.changedTraits).toEqual(['position']);
    });

    it('should handle tag traits as changed', () => {
        // Tag (true) vs tag (true) = no change
        const a: EntitySnapshot = { id: 1, traits: { tag: true } };
        const b: EntitySnapshot = { id: 1, traits: { tag: true } };

        expect(diffEntitySnapshots(a, b).changedTraits).toEqual([]);
    });

    it('should return sorted arrays', () => {
        const a: EntitySnapshot = { id: 1, traits: { position: { x: 0, y: 0 }, velocity: { vx: 1, vy: 2 }, health: { hp: 100 } } };
        const b: EntitySnapshot = { id: 1, traits: { score: { score: 0 } } };

        const result = diffEntitySnapshots(a, b);

        // removedTraits should contain position, velocity, health (sorted)
        expect(result.removedTraits).toEqual(['health', 'position', 'velocity']);
        // addedTraits should contain score
        expect(result.addedTraits).toEqual(['score']);
    });

    it('should throw Error if a is null', () => {
        expect(() => diffEntitySnapshots(null as any, { id: 1, traits: {} })).toThrow(Error);
    });

    it('should throw Error if b is undefined', () => {
        expect(() => diffEntitySnapshots({ id: 1, traits: {} }, undefined as any)).toThrow(Error);
    });

    it('should keep tag trait as changed when it flips to data trait', () => {
        const a: EntitySnapshot = { id: 1, traits: { tag: true } };
        const b: EntitySnapshot = { id: 1, traits: { tag: { some: 'data' } } };

        const result = diffEntitySnapshots(a, b);

        expect(result.changedTraits).toEqual(['tag']);
    });
});

