        entity.remove(Tag);
        entity.add(Velocity({ vx: 5, vy: 6 }));
        entity.remove(ChildOf(target));

        // Rollback to the snapshot
        rollbackWorld(world, registry, snapshot);

        // Verify state is restored
        const restoredEntity = world.entities.find((e) => e.id() === entity.id())!;
        expect(restoredEntity).toBeDefined();
        expect(restoredEntity.get(Position)).toEqual({ x: 10, y: 20 });
        expect(restoredEntity.has(Tag)).toBe(true);
        expect(restoredEntity.has(Velocity)).toBe(false);
        expect(restoredEntity.has(ChildOf(target))).toBe(true);
