        const before = snapshotEntity(world, entity, registry);

        entity.set(Position, { x: 5, y: 5 });
        entity.add(Velocity({ vx: 1, vy: 2 }));

        const after = snapshotEntity(world, entity, registry);

        const diff = diffEntitySnapshots(before, after);
        expect(diff.addedTraits).toEqual(['velocity']);
        expect(diff.changedTraits).toEqual(['position']);

        // Rollback to before state
        rollbackEntity(world, entity, registry, before);

        expect(entity.get(Position)).toEqual({ x: 1, y: 2 });
        expect(entity.has(Velocity)).toBe(false);
    });

    it('should support world snapshot diffing', () => {
        const e1 = world.spawn(Position({ x: 0, y: 0 }));
        const e2 = world.spawn(Tag);
        const e3 = world.spawn(Velocity({ vx: 1, vy: 2 }));

        const before = snapshotWorld(world, registry);

        // Mutate
        e1.set(Position, { x: 100, y: 200 });
        e2.destroy();
        const e4 = world.spawn(Position({ x: 50, y: 50 }));

        const after = snapshotWorld(world, registry);

        const diff = diffWorldSnapshots(before, after);

        expect(diff.removed).toContain(e2.id());
        expect(diff.added).toContain(e4.id());
        expect(diff.changed).toContain(e1.id());

        // Rollback to before state
        rollbackWorld(world, registry, before);

        expect(world.has(e1)).toBe(true);
        expect(e1.get(Position)).toEqual({ x: 0, y: 0 });
        expect(world.has(e2)).toBe(true);
        expect(world.has(e4)).toBe(false);
    });
});

