// ---------------------------------------------------------------------------
// diffEntitySnapshots
// ---------------------------------------------------------------------------

export function diffEntitySnapshots(
    a: EntitySnapshot,
    b: EntitySnapshot,
): { addedTraits: string[]; removedTraits: string[]; changedTraits: string[] } {
    if (a == null || b == null) {
        throw new Error('Cannot diff null or undefined entity snapshots');
    }

    const allKeys = new Set([...Object.keys(a.traits), ...Object.keys(b.traits)]);
    const addedTraits: string[] = [];
    const removedTraits: string[] = [];
    const changedTraits: string[] = [];

    for (const key of allKeys) {
        const inA = key in a.traits;
        const inB = key in b.traits;

        if (inA && !inB) {
            removedTraits.push(key);
        } else if (!inA && inB) {
            addedTraits.push(key);
        } else if (inA && inB) {
            // Both have it - check shallow equality
            if (!shallowEqual(a.traits[key], b.traits[key])) {
                changedTraits.push(key);
            }
        }
    }

    addedTraits.sort();
    removedTraits.sort();
    changedTraits.sort();

    return { addedTraits, removedTraits, changedTraits };
}

// ---------------------------------------------------------------------------
// diffWorldSnapshots
// ---------------------------------------------------------------------------

export function diffWorldSnapshots(
    before: WorldSnapshot,
    after: WorldSnapshot,
): { added: number[]; removed: number[]; changed: number[] } {
    if (before == null || after == null) {
        throw new Error('Cannot diff null or undefined world snapshots');
    }

    if (!Array.isArray(before.entities)) {
        throw new Error('World snapshot "before" is missing entities array');
    }

    if (!Array.isArray(after.entities)) {
        throw new Error('World snapshot "after" is missing entities array');
    }

    const beforeMap = new Map<number, EntitySnapshot>();
    const afterMap = new Map<number, EntitySnapshot>();

    for (const e of before.entities) beforeMap.set(e.id, e);
    for (const e of after.entities) afterMap.set(e.id, e);

    const allIds = new Set([...beforeMap.keys(), ...afterMap.keys()]);
    const added: number[] = [];
    const removed: number[] = [];
    const changed: number[] = [];

    for (const id of allIds) {
        const beforeEntity = beforeMap.get(id);
        const afterEntity = afterMap.get(id);

        if (!beforeEntity && afterEntity) {
            added.push(id);
        } else if (beforeEntity && !afterEntity) {
            removed.push(id);
        } else if (beforeEntity && afterEntity) {
            if (!entitySnapshotsEqual(beforeEntity, afterEntity)) {
                changed.push(id);
            }
        }
    }

    added.sort((a, b) => a - b);
    removed.sort((a, b) => a - b);
    changed.sort((a, b) => a - b);

    return { added, removed, changed };
}

/** Compare two EntitySnapshots ignoring key order and using shallow equality for data. */
function entitySnapshotsEqual(a: EntitySnapshot, b: EntitySnapshot): boolean {
    // Compare traits
    const aKeys = Object.keys(a.traits).sort();
    const bKeys = Object.keys(b.traits).sort();

    if (aKeys.length !== bKeys.length) return false;
    for (let i = 0; i < aKeys.length; i++) {
        if (aKeys[i] !== bKeys[i]) return false;
        if (!shallowEqual(a.traits[aKeys[i]], b.traits[bKeys[i]])) return false;
    }

    // Compare relations (treat {} as equivalent to undefined)
    const aRels = a.relations ?? {};
    const bRels = b.relations ?? {};
    const aRelKeys = Object.keys(aRels).sort();
    const bRelKeys = Object.keys(bRels).sort();

    if (aRelKeys.length !== bRelKeys.length) return false;
    for (let i = 0; i < aRelKeys.length; i++) {
        if (aRelKeys[i] !== bRelKeys[i]) return false;

        // Compare target arrays ignoring order
        const aTargets = aRels[aRelKeys[i]].slice().sort((x, y) => x.targetId - y.targetId);
        const bTargets = bRels[bRelKeys[i]].slice().sort((x, y) => x.targetId - y.targetId);

        if (aTargets.length !== bTargets.length) return false;
        for (let j = 0; j < aTargets.length; j++) {
            if (aTargets[j].targetId !== bTargets[j].targetId) return false;
            if (!shallowEqual(aTargets[j].data, bTargets[j].data)) return false;
        }
    }

    return true;
}

// ---------------------------------------------------------------------------
// Shallow equality helper
// ---------------------------------------------------------------------------

function shallowEqual(a: unknown, b: unknown): boolean {
    if (a === b) return true;

    if (typeof a !== 'object' || a === null || typeof b !== 'object' || b === null) {
        return a === b;
    }

    const keysA = Object.keys(a as Record<string, unknown>);
    const keysB = Object.keys(b as Record<string, unknown>);

    if (keysA.length !== keysB.length) return false;

    for (const key of keysA) {
        if (!(key in (b as Record<string, unknown>))) return false;
        if ((a as Record<string, unknown>)[key] !== (b as Record<string, unknown>)[key]) {
            return false;
        }
    }

    return true;
}
