// Compares dataUpdatedAt and errorUpdatedAt independently so that
// newer data is not discarded just because the other side has a newer
// error timestamp, and vice versa.
// eslint-disable-next-line @typescript-eslint/no-unnecessary-type-parameters
export function mergePersistedState<
  TData = unknown,
  TError = DefaultError,
>(
  liveState: QueryState<TData, TError>,
  persistedState: QueryState<TData, TError>,
): Partial<QueryState<TData, TError>> {
  // Decide which data to keep (newer dataUpdatedAt wins)
  const useLiveData = liveState.dataUpdatedAt >= persistedState.dataUpdatedAt

  // Decide which error to keep (newer errorUpdatedAt wins)
  const persistedErrorIsNewer =
    persistedState.errorUpdatedAt > liveState.errorUpdatedAt

  const merged: Partial<QueryState<TData, TError>> = {
    fetchStatus: 'idle',
    isInvalidated:
      liveState.isInvalidated || persistedState.isInvalidated,
  }

