    merged.data = liveState.data
    merged.dataUpdatedAt = liveState.dataUpdatedAt
    merged.dataUpdateCount = liveState.dataUpdateCount
  } else {
    merged.data = persistedState.data
    merged.dataUpdatedAt = persistedState.dataUpdatedAt
    merged.dataUpdateCount = persistedState.dataUpdateCount
