  // Determine which data to keep (newer dataUpdatedAt wins)
  const liveDataNewer = liveState.dataUpdatedAt >= persistedState.dataUpdatedAt;
  const persistedDataNewer = !liveDataNewer;

  // Determine which error to keep (newer errorUpdatedAt wins)
  const liveErrorNewer = liveState.errorUpdatedAt >= persistedState.errorUpdatedAt;
  const persistedErrorNewer = !liveErrorNewer;

