  if (liveErrorNewer) {
    merged.error = liveState.error;
    merged.errorUpdatedAt = liveState.errorUpdatedAt;
    merged.errorUpdateCount = liveState.errorUpdateCount;
    merged.fetchFailureCount = liveState.fetchFailureCount;
    merged.fetchFailureReason = liveState.fetchFailureReason;
