    expectTypeOf(Maybe.of(example)).toBeNever();
    expectTypeOf(Maybe.of(() => 'hello')).toEqualTypeOf<Maybe<() => string>>();

    const unknownVal: unknown = 123;
    expectTypeOf(Maybe.of(unknownVal)).toEqualTypeOf<Maybe<{}>>();

