        .with('a', (x) => 1)
        .with('b', (x) => 1)
        // @ts-expect-error
        .exhaustive();

      match(input)
        .with('a', (x) => {
          type t = Expect<Equal<typeof x, 'a'>>;
          return 1;
        })
        .with('b', (x) => {
          type t = Expect<Equal<typeof x, 'b'>>;
          return 2;
        })
