export type ValueOf<a> = a extends readonly any[] ? a[number] : a[keyof a];

export type Values<a extends object> = UnionToTuple<ValueOf<a>>;

/**
 * ### LeastUpperBound
 * An interesting one. A type taking two imbricated sets and returning the
 * smallest one.
 * We need that because sometimes the pattern's inferred type holds more
 * information than the value on which we are matching (if the value is any
 * or unknown for instance).
 */

export type LeastUpperBound<a, b> = b extends a ? b : a extends b ? a : never;

export type Contains<a, b> = a extends any
  ? 'exclude' extends {
      [k in keyof a]-?: Equal<a[k], b> extends true ? 'exclude' : 'include';
    }[keyof a]
    ? true
    : false
  : never;

// from https://stackoverflow.com/questions/50374908/transform-union-type-to-intersection-type/50375286#50375286
export type UnionToIntersection<union> = (
  union extends any ? (k: union) => void : never
) extends (k: infer intersection) => void
  ? intersection
  : never;

export type IsUnion<a> = [a] extends [UnionToIntersection<a>] ? false : true;

export type UnionToTuple<
  union,
  output extends any[] = []
> = UnionToIntersection<
  union extends any ? (t: union) => union : never
> extends (_: any) => infer elem
  ? UnionToTuple<Exclude<union, elem>, [elem, ...output]>
  : output;

export type Flatten<
  xs extends readonly any[],
  output extends any[] = []
> = xs extends readonly [infer head, ...infer tail]
  ? Flatten<tail, [...output, ...Extract<head, readonly any[]>]>
  : output;

export type Equal<a, b> = (<T>() => T extends a ? 1 : 2) extends <
  T
>() => T extends b ? 1 : 2
  ? true
  : false;

export type Expect<a extends true> = a;

export type IsAny<a> = 0 extends 1 & a ? true : false;

export type IsNever<T> = [T] extends [never] ? true : false;

export type Length<it extends readonly any[]> = it['length'];

export type Iterator<
  n extends number,
  it extends any[] = []
> = it['length'] extends n ? it : Iterator<n, [any, ...it]>;

export type Next<it extends any[]> = [any, ...it];
export type Prev<it extends any[]> = it extends readonly [any, ...infer tail]
  ? tail
  : [];

export type Take<
  xs extends readonly any[],
  it extends any[],
  output extends any[] = []
> = Length<it> extends 0
  ? output
  : xs extends readonly [infer head, ...infer tail]
  ? Take<tail, Prev<it>, [...output, head]>
  : output;

export type Drop<
  xs extends readonly any[],
  n extends any[]
> = Length<n> extends 0
  ? xs
  : xs extends readonly [any, ...infer tail]
  ? Drop<tail, Prev<n>>
  : [];

export type UpdateAt<
  tail extends readonly any[],
  n extends any[],
  value,
  inits extends readonly any[] = []
> = Length<n> extends 0
  ? tail extends readonly [any, ...infer tail]
    ? [...inits, value, ...tail]
    : inits
  : tail extends readonly [infer head, ...infer tail]
  ? UpdateAt<tail, Prev<n>, value, [...inits, head]>
  : inits;

export type BuiltInObjects =
  | Function
  | Date
  | RegExp
  | Generator
  | { readonly [Symbol.toStringTag]: string }
  | any[];

export type IsPlainObject<o, excludeUnion = BuiltInObjects> = o extends object
  ? // to excluded branded string types,
    // like `string & { __brand: "id" }`
    // and built-in objects
    o extends string | excludeUnion
    ? false
    : true
  : false;

export type Compute<a extends any> = a extends BuiltInObjects
  ? a
  : { [k in keyof a]: a[k] };

export type IntersectObjects<a> = (
  a extends any ? keyof a : never
) extends infer allKeys
  ? {
      [k in Extract<allKeys, PropertyKey>]: a extends any
        ? k extends keyof a
          ? a[k]
          : never
        : never;
    }
  : never;

export type WithDefault<a, def> = [a] extends [never] ? def : a;

export type IsLiteral<a> = [a] extends [null | undefined]
  ? true
  : [a] extends [string]
  ? string extends a
    ? false
    : true
  : [a] extends [number]
  ? number extends a
    ? false
    : true
  : [a] extends [boolean]
  ? boolean extends a
    ? false
    : true
  : [a] extends [symbol]
  ? symbol extends a
    ? false
    : true
  : [a] extends [bigint]
  ? bigint extends a
    ? false
    : true
  : false;

export type Primitives =
  | number
  | boolean
  | string
  | undefined
  | null
  | symbol
  | bigint;

export type NonLiteralPrimitive = Exclude<Primitives, undefined | null>;

export type TupleKeys = '0' | '1' | '2' | '3' | '4';

export type Union<a, b> = [b] extends [a] ? a : [a] extends [b] ? b : a | b;

/**
 * GuardValue returns the value guarded by a type guard function.
 */
export type GuardValue<fn> = fn extends (value: any) => value is infer b
  ? b
  : fn extends (value: infer a) => unknown
  ? a
  : never;

export type GuardFunction<input, narrowed> =
  | ((value: input) => value is Extract<narrowed, input>)
  | ((value: input) => boolean);

export type Some<bools extends boolean[]> = true extends bools[number]
  ? true
  : false;

export type All<bools extends boolean[]> = bools[number] extends true
  ? true
  : false;

export type Extends<a, b> = [a] extends [b] ? true : false;

export type Not<a extends boolean> = a extends true ? false : true;

type AllKeys<a> = a extends any ? keyof a : never;

// Merge unions of objects into a single object with unions of keys
export type MergeUnion<a> =
  | {
      [k in AllKeys<a>]: a extends any
        ? k extends keyof a
          ? a[k]
          : never
        : never;
    }
  | never;

export type IsFixedSizeTuple<a extends readonly any[]> = IsLiteral<Length<a>>;

// is it a fixed size or a variadic tuple
export type IsTuple<a> = a extends
  | readonly []
  | readonly [any, ...any]
  | readonly [...any, any]
  ? true
  : false;

export type IsStrictArray<a extends readonly any[]> = Not<IsTuple<a>>;

export type IsReadonlyArray<a> = a extends readonly any[]
  ? a extends any[] // mutable array
    ? false
    : true
  : false;

export type MaybeAddReadonly<
  a,
  shouldAdd extends boolean
> = shouldAdd extends true ? Readonly<a> : a;

export type MapKey<T> = T extends Map<infer K, any> ? K : never;

export type MapValue<T> = T extends Map<any, infer V> ? V : never;

export type SetValue<T> = T extends Set<infer V> ? V : never;

export type RecordKey<T> = T extends Record<infer K, any> ? K : never;

export type RecordValue<T> = T extends Record<any, infer V> ? V : never;

export type ReadonlyArrayValue<T> = T extends ReadonlyArray<infer V>
  ? V
  : never;

export type ExtractPlainObject<T> = T extends any
  ? IsPlainObject<T> extends true
    ? T
    : never
  : never;

export type GetKey<O, K> = O extends any
  ? K extends keyof O
    ? O[K]
    : never
  : never;

export interface Fn {
  input: unknown;
  output: unknown;
}

export type Call<fn extends Fn, input> = (fn & {
  input: input;
})['output'];

export type IsOptionalKeysOf<obj, key extends keyof obj> = {} extends Pick<
  obj,
  key
>
  ? true
  : false;

export type Option<a> = { kind: 'none' } | { kind: 'some'; value: a };

export const none: Option<never> = { kind: 'none' };
export const some = <a>(value: a): Option<a> => ({
  kind: 'some',
  value,
});

export type Blog = {
  id: number;
  title: string;
};

export type State =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'success'; data: string }
  | { status: 'error'; error: Error };

export type Event =
  | { type: 'fetch' }
  | { type: 'success'; data: string; requestTime?: number }
  | { type: 'error'; error: Error }
  | { type: 'cancel' };

export type BigUnion =
  | 'a'
  | 'b'
  | 'c'
  | 'd'
  | 'e'
  | 'f'
  | 'g'
  | 'h'
  | 'i'
  | 'j'
  | 'k'
  | 'l'
  | 'm'
  | 'n'
  | 'o'
  | 'p'
  | 'q'
  | 'r'
  | 's'
  | 't'
  | 'u'
  | 'v'
  | 'w'
  | 'x'
  | 'y'
  | 'z';

type AsyncResultStatus = 'idle' | 'loading' | 'error' | 'success';

export interface BaseAsyncResult<TData, TError = Error> {
  status: AsyncResultStatus;
  data?: TData;
  error?: TError;
}

export interface AsyncResultIdleOrLoading<TData, TError = Error>
  extends BaseAsyncResult<TData, TError> {
  status: 'idle' | 'loading';
}

export interface AsyncResultSuccess<TData, TError = Error>
  extends BaseAsyncResult<TData, TError> {
  status: 'success';
  data: TData;
}

export interface AsyncResultError<TData, TError = Error>
  extends BaseAsyncResult<TData, TError> {
  status: 'error';
  error: TError;
}
export type AsyncResult<TData, TError = Error> =
  | AsyncResultIdleOrLoading<TData, TError>
  | AsyncResultSuccess<TData, TError>
  | AsyncResultError<TData, TError>;

import { Expect, Equal } from '../src/types/helpers';
import { match, P, Pattern } from '../src';
import { Option, State } from './types-catalog/utils';

describe('when', () => {
  it('should work for simple cases', () => {
    const values = [
      { value: 1, expected: false },
      { value: -2, expected: false },
      { value: 3, expected: false },
      { value: 100, expected: false },
      { value: 20, expected: true },
      { value: 39, expected: true },
    ];

    values.forEach(({ value, expected }) => {
      expect(
        match(value)
          .with(
            P.when((x) => x > 10 && x < 50),
            () => true
          )
          .otherwise(() => false)
      ).toEqual(expected);
    });
  });

  it('should narrow down the value type based on type guard', () => {
    let n = 20;
    const res = match(n)
      .with(
        P.when((x): x is 13 => x === 13),
        (x) => {
          type t = Expect<Equal<typeof x, 13>>;
          return true;
        }
      )
      .otherwise(() => false);

    type t = Expect<Equal<typeof res, boolean>>;
  });

  it('should be able to correcly narrow a generic types', () => {
    const map = <A, B>(option: Option<A>, mapper: (value: A) => B): Option<B> =>
      match<Option<A>, Option<B>>(option)
        .when(
          (option): option is { kind: 'some'; value: A } =>
            option.kind === 'some',
          (option) => ({
            kind: 'some',
            value: mapper(option.value),
          })
        )
        .when(
          (option): option is { kind: 'none' } => option.kind === 'none',
          (option) => option
        )
        .run();

    const input = { kind: 'some' as const, value: 20 };
    const expectedOutput = { kind: 'some' as const, value: `number is 20` };

    const res = map(input, (x) => `number is ${x}`);

    type t = Expect<Equal<typeof res, Option<string>>>;

    expect(res).toEqual(expectedOutput);
  });

  it('should correctly infer the input type, even when used in another function pattern', () => {
    const f = (x: { a: number[] }) =>
      match(x)
        .with(
          {
            a: P.array(
              P.when((x) => {
                type t = Expect<Equal<typeof x, number>>;
                return true;
              })
            ),
          },
          () => 'true'
        )
        .otherwise(() => 'false');
  });

  it('should accept other values  than booleans in output', () => {
    const f = (x: { a: number[] }) =>
      match(x)
        .with(
          {
            a: P.when(() => {
              return 'anything truthy';
            }),
          },
          () => 'true'
        )
        .otherwise(() => 'false');

    expect(f({ a: [] })).toEqual('true');
  });

  describe('`with` with `when` clauses', () => {
    it('should work for simple cases', () => {
      const values: { value: State; expected: boolean }[] = [
        { value: { status: 'success', data: 'yo' }, expected: false },
        { value: { status: 'success', data: 'coucou' }, expected: true },
        { value: { status: 'idle' }, expected: false },
        { value: { status: 'loading' }, expected: false },
      ];

      values.forEach(({ value, expected }) => {
        expect(
          match(value)
            .with(
              { status: 'success' },
              (x) => x.data.length > 3,
              (x) => {
                type t = Expect<
                  Equal<typeof x, { status: 'success'; data: string }>
                >;
                return true;
              }
            )
            .with(
              { status: 'success', data: P.select('data') },
              (x) => x.data.length > 3 && x.data.length < 10,
              (x) => {
                type t = Expect<Equal<typeof x, { data: string }>>;
                return true;
              }
            )
            .with(
              { status: 'success', data: P.select('data') },
              (x) =>
                x.data.length > 3 && x.data.length < 10 && x.data.length % 2,
              (x) => {
                type t = Expect<Equal<typeof x, { data: string }>>;
                return true;
              }
            )
            .otherwise(() => false)
        ).toEqual(expected);
      });
    });

    it('type should be refined in each guard clause', () => {
      const values: { value: number | string; expected: string }[] = [
        { value: -1, expected: 'x: number' },
        { value: 2, expected: '2' },
        { value: 5, expected: '2 < x < 10' },
        { value: 100, expected: 'x: number' },
        { value: '100', expected: '2 < x.length < 10' },
        { value: 'Gabriel Vergnaud', expected: 'x: string' },
      ];

      values.forEach(({ value, expected }) => {
        const res = match(value)
          .with(
            P.any,
            (x): x is 2 => x === 2,
            (x) => {
              type t = Expect<Equal<typeof x, 2>>;
              return '2';
            }
          )
          .with(
            P.string,
            (x) => x.length > 2 && x.length < 10,
            () => '2 < x.length < 10'
          )
          .with(
            P.number,
            (x) => x > 2 && x < 10,
            () => '2 < x < 10'
          )
          .with(
            P.any,
            (x): x is number => typeof x === 'number',
            (x) => {
              type t = Expect<Equal<typeof x, number>>;
              return 'x: number';
            }
          )
          .with(P.string, () => 'x: string')
          .exhaustive();

        expect(res).toEqual(expected);
      });
    });
  });

  it('should narrow the type of the input based on the pattern', () => {
    type Option<T> = { type: 'some'; value: T } | { type: 'none' };

    const optionalFizzBuzz = (
      optionalNumber: Option<{
        opt?: 'x' | 'y';
        list: {
          test: 'a' | 'b';
          sublist: ('z' | 'w')[];
          prop: string;
          maybe?: string | number;
        }[];
        coords: { x: 'left' | 'right'; y: 'top' | 'bottom' };
      }>
    ) =>
      match(optionalNumber)
        .with(
          {
            type: 'some',
            value: {
              list: P.array({
                test: 'a',
                sublist: ['w'],
                maybe: P.string.optional(),
                prop: P.when((x) => {
                  type t = Expect<Equal<typeof x, string>>;
                  return true;
                }),
              }),
              opt: P.optional('x'),
            },
          },
          (x) => {
            type t = Expect<
              Equal<
                typeof x,
                {
                  type: 'some';
                  value: {
                    opt?: 'x' | undefined;
                    list: {
                      test: 'a';
                      sublist: ['w'];
                      prop: string;
                      maybe?: string | undefined;
                    }[];
                    coords: {
                      x: 'left' | 'right';
                      y: 'top' | 'bottom';
                    };
                  };
                }
              >
            >;
            return 'ok';
          }
        )
        .with(
          {
            type: 'some',
            value: {
              coords: P.not({ x: 'left' }),
            },
          },
          (x) => {
            type t = Expect<
              Equal<
                (typeof x)['value']['coords'],
                {
                  y: 'top' | 'bottom';
                  x: 'right';
                }
              >
            >;

            return 'ok';
          }
        )
        .with(
          {
            type: 'some',
            value: {
              list: P.array({ test: 'a', prop: P.select() }),
            },
          },
          (x) => {
            type t = Expect<Equal<typeof x, string[]>>;
          }
        )
        .with({ type: 'none' }, () => null)
        .with({ type: 'some' }, () => 'ok')
        .exhaustive();
  });

  it('should narrow the type of the input based on the pattern', () => {
    const optionalFizzBuzz = (optionalNumber: Option<number>) =>
      match(optionalNumber)
        // You can add up to 3 guard functions after your
        // pattern. They must all return true for the
        // handler to be executed.
        .with(
          { kind: 'some' },
          // `someNumber` is inferred to be a { kind: "some"; value: number }
          // based on the pattern provided as first argument.
          (someNumber) =>
            someNumber.value % 5 === 0 && someNumber.value % 3 === 0,
          () => 'fizzbuzz'
        )
        .with(
          {
            kind: 'some',
          },
          // you can also use destructuring
          ({ value }) => value % 5 === 0,
          () => 'buzz'
        )

        // Or you can use a `when` pattern, to apply your guard to
        // a subset of your input.
        .with(
          {
            kind: 'some',
            value: Pattern.when((value) => value % 3 === 0),
          },
          () => 'fizz'
        )
        // for all other numbers, just convert them to a string.
        .with({ kind: 'some' }, ({ value }) => value.toString())
        // if it's a none, return "nope"
        .with({ kind: 'none' }, () => 'nope')
        .exhaustive();
  });

  it('should be possible to hard code type parameters to P.when', () => {
    const regex = <input>(expr: RegExp) =>
      P.when<
        input | string, // input
        string, // narrowed value
        never // types excluded
      >((x): x is string => typeof x === 'string' && expr.test(x));

    type Input = string | { prop: string | number };

    expect(
      match<Input>('Hello')
        .with(regex(/^H/), () => true)
        .with({ prop: regex(/^H/) }, (x) => {
          type t = Expect<Equal<typeof x, { prop: string }>>;
          return true;
        })
        // @ts-expect-error
        .exhaustive()
    ).toBe(true);
  });

  it('should be possible to do some manipulations on the input type', () => {
    const notString = <input>() =>
      P.when<
        input | string, // input
        Exclude<input, string>, // narrowed value
        never // types excluded
      >((x): x is Exclude<input, string> => typeof x !== 'string');

    type Input = { prop: string | number };

    expect(
      match<Input>({ prop: 20 })
        .with({ prop: notString() }, (x) => {
          type t = Expect<Equal<typeof x, { prop: number }>>;
          return true;
        })
        // @ts-expect-error
        .exhaustive()
    ).toBe(true);
  });

  it('issue #153: P.when should preserve undefined.', () => {
    type Data = { digit: number };

    type Input = {
      data: Data | undefined;
    };

    const input: Input = { data: undefined };

    const result = match(input)
      .with(
        {
          data: P.when((data) => {
            type t = Expect<Equal<typeof data, Data | undefined>>;
            return data ? data.digit > 5 : 0;
          }),
        },
        () => 'digit is more than 5'
      )
      .otherwise(() => 'digit is less than 5');

    expect(result).toBe('digit is less than 5');
  });
});

