        .with(P.string, (x) => `also matched string: ${x}`)
        .with(P.number, (x) => `number: ${x}`)
        .run();

      expect(result).toEqual([
        'matched string: hello',
        'also matched string: hello',
      ]);
    });

    it('should return all matching results in clause order', () => {
      const result = matchEach<string | number | boolean>('hello')
        .with(P.string, (x) => 1)
        .with(P.number, (x) => 2)
        .with(P.string, (x) => 3)
        .run();

      expect(result).toEqual([1, 3]);
    });

    it('should match union type members with object patterns', () => {
      type Input =
        | { type: 'a'; value: string }
        | { type: 'b'; value: number };
      const input = { type: 'a', value: 'hello' } as Input;

      const result = matchEach(input)
        .with({ type: 'a' }, (x) => `a: ${x.value}`)
        .with({ type: 'b' }, (x) => `b: ${x.value}`)
        .run();

      expect(result).toEqual(['a: hello']);
    });

    it('should collect from all matching when multiple match', () => {
      const result = matchEach<number>(5)
        .with(P.when((x) => x > 0), (x) => 'positive')
        .with(P.when((x) => x < 10), (x) => 'less than 10')
        .with(P.when((x) => x > 3), (x) => 'greater than 3')
        .run();

      expect(result).toEqual(['positive', 'less than 10', 'greater than 3']);
