    it('should enforce compile-time exhaustiveness', () => {
      type Input = 'a' | 'b' | 'c';

      matchEach('a' as Input)
        .with('a' as const, () => 1)
        .with('b' as const, () => 2)
        .with('c' as const, () => 3)
