export class MapConflictError extends Error {
  /**
   * @param {string} message
   * @param {Array<MapConflict>} conflicts
   */
  constructor (message, conflicts) {
    super(message)
    this.name = 'MapConflictError'
    /**
     * Array of conflict objects describing each conflicting key write.
     * @type {Array<MapConflict>}
     */
    this.conflicts = conflicts
  }
}

/**
 * @typedef {Object} MapConflictWrite
 * @property {MapConflictSnapshot} snapshot
 */

/**
 * @typedef {Object} MapConflictSnapshot
 * @property {string} summary - Non-empty description of the write
 */

/**
 * @typedef {Object} MapConflictResolution
 * @property {string} winner - Description of which write won
 * @property {string} strategy - The strategy used ('allow', 'collect', or 'error')
 * @property {boolean} deterministic - Whether the resolution is deterministic
 */

/**
 * @typedef {Object} MapConflict
 * @property {string} key - The map key that conflicted
 * @property {string} parentId - The ID of the parent type
 * @property {string} type - The conflict type ('set-set' or 'delete-set')
 * @property {string} source - 'local', 'remote', or 'mixed'
 * @property {string} message - Human-readable description
 * @property {Array<MapConflictWrite>} writes - The colliding writes
 * @property {MapConflictResolution} resolution - How the conflict was resolved
 * @property {boolean} [ambiguous] - Whether this conflict involves Yjs types or subdocs
 */

/**
 * @param {import('../ytype.js').YType} parent
 * @param {import('../structs/Item.js').Item} item
 * @return {string}
 */
export const getParentId = (parent) => {
  if (parent._item) {
    return String(parent._item.id.client) + ':' + String(parent._item.id.clock)
  }
  return 'root'
}

/**
 * Determine if an item's content is a Yjs type or subdoc (making conflicts ambiguous).
 * @param {import('../structs/Item.js').Item} item
 * @return {boolean}
 */
export const isAmbiguousContent = (item) => {
  const { ContentType, ContentDoc } = /** @type {any} */ (globalThis)
  const ctor = item.content.constructor
  return ctor.name === 'ContentType' || ctor.name === 'ContentDoc'
}

/**
 * Build a summary string for a map write operation.
 * @param {import('../structs/Item.js').Item} item
 * @param {string} writeType
 * @return {string}
 */
export const buildWriteSummary = (item, writeType) => {
  if (writeType === 'delete') {
    return 'delete'
  }
  try {
    const val = item.content.getContent()
    const display = val && val.length > 0 ? String(val[val.length - 1]) : 'unknown'
    return 'set: ' + display.substring(0, 80)
  } catch (e) {
    return 'set: <value>'
  }
}

/**
 * Apply the map conflict policy for a detected conflict.
 *
 * @param {import('./Doc.js').Doc} doc
 * @param {import('../utils/Transaction.js').Transaction} transaction
 * @param {string} key
 * @param {import('../ytype.js').YType} parent
 * @param {string} type - 'set-set' or 'delete-set'
 * @param {string} source - 'local', 'remote', or 'mixed'
 * @param {Array<{item: import('../structs/Item.js').Item|null, type: string}>} writes
 */
export const handleMapConflict = (doc, transaction, key, parent, type, source, writes) => {
  const policy = doc._mapConflictPolicy || 'allow'
  if (policy === 'allow') {
    return
  }

  const parentId = getParentId(parent)
  const ambiguous = writes.some(w => w.item && isAmbiguousContent(w.item))

  const conflict = {
    key,
    parentId,
    type,
    source,
    message: `Conflicting map writes on key "${key}" (type: ${type})`,
    writes: writes.map(w => ({
      snapshot: {
        summary: buildWriteSummary(/** @type {import('../structs/Item.js').Item} */ (w.item), w.type)
      }
    })),
    resolution: {
      winner: 'last-write-wins (Yjs CRDT)',
      strategy: policy,
      deterministic: true
    },
    ambiguous
  }

  if (policy === 'error') {
    throw new MapConflictError(
      `Conflicting map writes detected on key "${key}" (${type}). ` +
      `Conflicts: [${writes.map(w => w.type).join(', ')}].`,
      [conflict]
    )
  } else if (policy === 'collect') {
    doc._mapConflicts.push(conflict)
  }
}
