// syntaxErrorCheck checks that the error is a *orderedmap.SyntaxError and its Error() matches
// the expected format.
func syntaxErrorCheck(t *testing.T, err error, msg string, pos int) {
	t.Helper()
	if err == nil {
		t.Fatalf("expected SyntaxError, got nil")
	}
	se, ok := err.(*orderedmap.SyntaxError)
	if !ok {
		t.Fatalf("expected *orderedmap.SyntaxError, got %T", err)
	}
	if se.Message != msg {
		t.Fatalf("expected message %q, got %q", msg, se.Message)
	}
	if se.Position != pos {
		t.Fatalf("expected position %d, got %d", pos, se.Position)
	}
	expectedErr := "syntax error at position " + itoa(pos) + ": " + msg
	if se.Error() != expectedErr {
		t.Fatalf("expected Error() %q, got %q", expectedErr, se.Error())
	}
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	s := ""
	for n > 0 {
		s = string(rune('0'+n%10)) + s
		n /= 10
	}
	return s
}

// newMap creates an orderedmap.Map with the given key/value pairs.
func newMap(kv ...interface{}) *orderedmap.Map {
	m := orderedmap.NewMap()
	for i := 0; i < len(kv); i += 2 {
		m.Set(kv[i], kv[i+1])
	}
	return m
}

