		exp  []interface{}
	}{
		{"$.name", []interface{}{"hello"}},
		{"$.my-key", []interface{}{"world"}},
		{"$.a", []interface{}{newMap("b", newMap("c", 42))}},
		{"$.a.b", []interface{}{newMap("c", 42)}},
		{"$.a.b.c", []interface{}{42}},
	}
	for _, tt := range tests {
		res, err := orderedmap.Query(doc, tt.path)
