			t.Fatalf("path %q: expected %d results, got %d", tt.path, len(tt.exp), len(res))
		}
		for i := range res {
			if res[i] != tt.exp[i] {
				t.Fatalf("path %q result[%d]: got %v, expected %v", tt.path, i, res[i], tt.exp[i])
			}
		}
	}
}

