	if len(res) != 2 {
		t.Fatalf("expected 2 results, got %d", len(res))
	}
}

func TestQuery_RecursiveDescentOnNestedArrays(t *testing.T) {
	doc := newMap("data", []interface{}{
		newMap("id", 1),
		newMap("id", 2, "nested", newMap("id", 3)),
	})
	res, err := orderedmap.Query(doc, "$..id")
	if err != nil {
		t.Fatal(err)
	}
	if len(res) != 3 {
		t.Fatalf("expected 3 results, got %d: %v", len(res), res)
	}
}

