	doc := []interface{}{
		newMap("my-key", 10),
		newMap("my-key", 20),
	}
	res, err := orderedmap.Query(doc, "$[?(@.my-key == 10)]")
	if err != nil {
		t.Fatal(err)
	}
	if len(res) != 1 {
		t.Fatalf("expected 1 result, got %d", len(res))
	}
}

func TestQuery_BracketHyphenKey(t *testing.T) {
	doc := newMap("my-key", "value")
	res, err := orderedmap.Query(doc, "$['my-key']")
	if err != nil {
		t.Fatal(err)
	}
	if len(res) != 1 || res[0] != "value" {
		t.Fatalf("expected ['value'], got %v", res)
	}
}

func TestQuery_RecursiveBracketKeys(t *testing.T) {
	doc := newMap("a", newMap("x", 1, "y", 2), "b", newMap("x", 3))
	res, err := orderedmap.Query(doc, "$..['x','y']")
	if err != nil {
		t.Fatal(err)
	}
	if len(res) != 3 {
		t.Fatalf("expected 3 results, got %d: %v", len(res), res)
	}
}
"}

